let a = [1];
let b = a;
a.push(2);
console.log(b.length);

What is the time complexity of the following code? 
for (int i = 0; i < n; i++) 
  for (int j = 1; j < n; j = j * 2) 
    print(i, j);

What is the output of the following code?
i = 5
while i > 0:
    i -= 1
    if i == 2:
        break
else:
    print("Done")

